//#region src/SvtaErrorCategory.ts
/**
* SVTA error category 0: Unknown error
*
* @public
*/
const SVTA_ERROR_CATEGORY_UNKNOWN = 0;
/**
* SVTA error category 1: Issues with the content itself, such as an unsupported format
*
* @public
*/
const SVTA_ERROR_CATEGORY_MEDIA_CONTENT = 1;
/**
* SVTA error category 2: Player unable to sustain the experience
*
* @public
*/
const SVTA_ERROR_CATEGORY_PLAYBACK = 2;
/**
* SVTA error category 3: Issues on the network, including unavailable resources
*
* @public
*/
const SVTA_ERROR_CATEGORY_NETWORK = 3;
/**
* SVTA error category 4: Security related error, including authentication or entitlement issues
*
* @public
*/
const SVTA_ERROR_CATEGORY_CONTENT_PROTECTION = 4;
/**
* SVTA error category 5: Defective captions or audio description
*
* @public
*/
const SVTA_ERROR_CATEGORY_ACCESSIBILITY = 5;
/**
* SVTA error category 6: Framework supporting the play out of the stream on a second device
*
* @public
*/
const SVTA_ERROR_CATEGORY_REMOTE_PLAY = 6;
/**
* SVTA error category 7: Issues triggered by ad insertion
*
* @public
*/
const SVTA_ERROR_CATEGORY_ADVERTISING = 7;
/**
* SVTA error category 99: Reserved category for Publisher-defined errors
*
* @public
*/
const SVTA_ERROR_CATEGORY_CUSTOM = 99;
/**
* SVTA standardized error code categories. The category of an error code
* occupies its thousands digits: `Math.floor(code / 1000)` yields the
* category of any SVTA error code.
*
* @see {@link https://www.svta.org/product/svta2070/ | SVTA2070: Standardized Error Codes}
*
* @enum
*
* @public
*/
const SvtaErrorCategory = {
	/**
	* Unknown error
	*/
	UNKNOWN: 0,
	/**
	* Issues with the content itself, such as an unsupported format
	*/
	MEDIA_CONTENT: 1,
	/**
	* Player unable to sustain the experience
	*/
	PLAYBACK: 2,
	/**
	* Issues on the network, including unavailable resources
	*/
	NETWORK: 3,
	/**
	* Security related error, including authentication or entitlement issues
	*/
	CONTENT_PROTECTION: 4,
	/**
	* Defective captions or audio description
	*/
	ACCESSIBILITY: 5,
	/**
	* Framework supporting the play out of the stream on a second device
	*/
	REMOTE_PLAY: 6,
	/**
	* Issues triggered by ad insertion
	*/
	ADVERTISING: 7,
	/**
	* Reserved category for Publisher-defined errors
	*/
	CUSTOM: 99
};
//#endregion
//#region src/getSvtaErrorCategory.ts
/**
* Get the `SvtaErrorCategory` of an SVTA error code, per the spec's
* `code / 1000` rule.
*
* @param code - An SVTA error code.
* @returns The error category. Returns `undefined` if the code is not a
* non-negative integer, or if the spec does not assign its category.
* Categories 8-98 and above 99 are reserved for future use.
*
* @public
*
* @example
* {@includeCode ../test/getSvtaErrorCategory.test.ts#example}
*/
function getSvtaErrorCategory(code) {
	if (!Number.isInteger(code)) return;
	const category = Math.floor(code / 1e3);
	if (category >= SvtaErrorCategory.UNKNOWN && category <= SvtaErrorCategory.ADVERTISING || category === SvtaErrorCategory.CUSTOM) return category;
}
//#endregion
//#region src/getSvtaErrorIndex.ts
/**
* Get the error index of an SVTA error code, per the spec's
* `code mod 1000` rule. The index identifies the specific error within
* its category: native indices are 0-99, embedded external codes (HTTP,
* VAST) are 100-999.
*
* @param code - An SVTA error code.
* @returns The error index within the code's category, or `undefined`
* if the code is not a non-negative integer.
*
* @public
*
* @example
* {@includeCode ../test/getSvtaErrorIndex.test.ts#example}
*/
function getSvtaErrorIndex(code) {
	if (!Number.isInteger(code) || code < 0) return;
	return code % 1e3;
}
//#endregion
//#region src/httpStatusToSvtaErrorCode.ts
/**
* Embed an HTTP response status code into the SVTA Network error
* category, per the external code embedding rule of SVTA2070. HTTP 404
* becomes 3404.
*
* Values outside the valid HTTP status range (integers 100-599) return
* the unknown network error code (3000) rather than throwing, so error
* reporting paths cannot fail.
*
* @param status - An HTTP response status code (100-599).
* @returns The SVTA network error code embedding the status.
*
* @public
*
* @example
* {@includeCode ../test/httpStatusToSvtaErrorCode.test.ts#example}
*/
function httpStatusToSvtaErrorCode(status) {
	const base = SvtaErrorCategory.NETWORK * 1e3;
	if (!Number.isInteger(status) || status < 100 || status > 599) return base;
	return base + status;
}
//#endregion
